"""Execution-grounded verification of agent-authored workspaces.

Five gates, each of which either runs the code or performs AST analysis on it:

    syntax     Every authored .py file must parse (`ast.parse`). Empty
               workspaces (0 Python files) return `FAILED`.
    build      Packaging metadata (`pyproject.toml`, `setup.py`, or `setup.cfg`)
               must exist and be valid/installable. When `pyproject.toml` is
               present, validate it with `tomllib` (must parse as valid TOML and
               contain at least one of `[project]`, `[build-system]`, or
               `[tool]` tables; an empty or malformed `pyproject.toml` returns
               `FAILED`), and run `pip install -e . --no-deps --no-build-isolation`
               when `pip` is available.
    smoke      Non-test authored modules must import in a subprocess with both
               `workdir` and `os.path.join(workdir, "src")` on `PYTHONPATH`. If
               no importable modules exist or any module fails with a syntax or
               runtime error, return `FAILED`. If module imports fail solely
               with `ModuleNotFoundError` for uninstalled third-party packages
               (e.g. `opentelemetry`), return `SKIPPED` (not `FAILED`).
    tests      Discover test files (`"test" in os.path.basename(p).lower()`;
               if none exist, return `FAILED`) and run them with both `workdir`
               and `os.path.join(workdir, "src")` on `PYTHONPATH`. Use `pytest`
               if installed in `self.python`; otherwise run a stdlib fallback
               subprocess that imports each test file and collects/executes BOTH
               bare `def test_*()` functions (taking 0 required args) AND
               `unittest.TestCase` subclasses (because `unittest discover`
               ignores bare `def test_*()` functions). If 0 tests are collected
               because of `ModuleNotFoundError` for an uninstalled third-party
               package, return `SKIPPED`.
    telemetry  AST analysis of authored `.py` files must find BOTH (1) an actual
               `import opentelemetry` or `from opentelemetry ... import ...`
               node AND (2) at least one AST `Call` to a tracer/span method or
               function (`start_as_current_span`, `start_span`, `get_tracer`,
               `get_tracer_provider`, `set_tracer_provider`, `get_meter`). A
               comment/docstring mention or a bare `import opentelemetry`
               without any tracer/span call must return `FAILED`.

Each result carries the `method` used to reach it. A gate that could not be
evaluated returns `SKIPPED` rather than `PASSED`, so a missing tool can never be
mistaken for a success, and `SKIPPED` gates are excluded from the fitness
denominator (`evaluated_gates` and `score_penalty`) rather than scored as
failures (`score_penalty = failed_gate_count * penalty_per_gate`).

The V1 verifier this replaces executed nothing in three of its four gates:
`build` was a filename substring match, `smoke` was `len(files) >= 3`, and
`telemetry` searched text that included the CEO's markdown prose, so an essay
mentioning OpenTelemetry passed. Six generations were selected on those
signals. The whole design rule here is that no gate may be satisfiable by
writing about it.

Usage:
    from hae.evaluation.harness import ExecutionHarness

    harness = ExecutionHarness()
    report = harness.verify_workspace(workspace, deliverable_text)
    print(report.summary(), report.gate_status)
"""

import ast
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

from hae.evaluation.artifacts import filter_bundle, is_generated_path, is_malformed_path

SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        parts = []
        for g in self.gates:
            parts.append(f"{g.name}: {g.status} ({g.method})")
        return f"Report: {self.source}, {self.authored_files} files, {self.python_files} py. " + "; ".join(parts)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```lang\n...content...\n```
    # We look for blocks that might have a filename in the info string or just code.
    # The spec says "path->content map". Usually agents write:
    # ```python
    # # path: src/main.py
    # ...
    # ```
    # OR
    # ```src/main.py
    # ...
    # ```

    blocks = {}
    # Find all fenced blocks
    pattern = r'```([^\n]*)\n(.*?)\n```'
    matches = re.finditer(pattern, text, re.DOTALL)

    for match in matches:
        info_string = match.group(1).strip()
        content = match.group(2)

        path = None
        # Try to extract path from info string
        # Common patterns: "python", "src/main.py", "path/to/file.py"
        if info_string:
            # If it looks like a path (contains / or .py), use it
            if '/' in info_string or info_string.endswith('.py'):
                path = info_string
            else:
                # Check for "# path: ..." inside the content
                path_match = re.search(r'#\s*path:\s*(\S+)', content)
                if path_match:
                    path = path_match.group(1)

        if not path:
            # Fallback: try to find a path comment in the first few lines
            lines = content.split('\n')
            for line in lines[:5]:
                path_match = re.search(r'#\s*path:\s*(\S+)', line)
                if path_match:
                    path = path_match.group(1)
                    break

        if path:
            # Sanitize path slightly (strip whitespace)
            path = path.strip()
            if path:
                blocks[path] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            try:
                if hasattr(workspace, 'export_bundle'):
                    bundle = workspace.export_bundle()
                    source = 'workspace'
                elif hasattr(workspace, 'files'):
                    # Assume dict-like
                    bundle = dict(workspace.files)
                    source = 'workspace'
            except Exception:
                pass

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter out generated/malformed paths
        filtered_bundle = filter_bundle(bundle)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in filtered_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=filtered_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Skip generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        python_files = [p for p in authored if p.endswith('.py')]
        authored_files_count = len(authored)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, python_files))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=len(python_files),
            source=source
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='syntax', status=FAILED, method='ast', detail='No Python files found', duration_s=time.time() - start)

        errors = []
        for py_file in python_files:
            full_path = os.path.join(workdir, py_file)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{py_file}: {e}")
            except Exception as e:
                errors.append(f"{py_file}: {e}")

        elapsed = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast', detail='; '.join(errors), duration_s=elapsed)
        return GateResult(name='syntax', status=PASSED, method='ast', detail='All files parse', duration_s=elapsed)

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(name='build', status=FAILED, method='fs', detail='No packaging metadata found', duration_s=time.time() - start)

        # Validate pyproject.toml if present
        if has_pyproject:
            if tomllib is None:
                return GateResult(name='build', status=SKIPPED, method='tomllib', detail='tomllib not available', duration_s=time.time() - start)

            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)

                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ('project', 'build-system', 'tool')):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml missing required tables', duration_s=time.time() - start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time() - start)

        # Try pip install
        pip_cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], capture_output=True, timeout=10)

            proc = subprocess.run(
                pip_cmd,
                cwd=workdir,
                capture_output=True,
                timeout=self.timeout_s
            )
            elapsed = time.time() - start
            if proc.returncode == 0:
                return GateResult(name='build', status=PASSED, method='pip', detail='Installed successfully', duration_s=elapsed)
            else:
                stderr = proc.stderr.decode('utf-8', errors='replace')
                return GateResult(name='build', status=FAILED, method='pip', detail=f'pip install failed: {stderr}', duration_s=elapsed)
        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip', detail='pip not found', duration_s=time.time() - start)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip', detail='pip install timed out', duration_s=time.time() - start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip', detail=f'pip error: {e}', duration_s=time.time() - start)

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test modules
        modules = []
        for path in authored:
            if path.endswith('.py') and 'test' not in os.path.basename(path).lower():
                # Convert path to module name
                # src/main.py -> main (if src is on path) or src.main
                # We will add workdir and workdir/src to PYTHONPATH
                rel_path = path
                if rel_path.startswith('src/'):
                    mod_name = rel_path[4:-3].replace('/', '.')
                else:
                    mod_name = rel_path[:-3].replace('/', '.')
                modules.append(mod_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import', detail='No importable modules found', duration_s=time.time() - start)

        # Construct PYTHONPATH
        env = os.environ.copy()
        pypath = [workdir, os.path.join(workdir, 'src')]
        env['PYTHONPATH'] = os.pathsep.join(pypath + [env.get('PYTHONPATH', '')])

        # Try importing each module
        import_errors = []
        module_not_found_errors = []

        for mod in modules:
            code = f"import {mod}"
            try:
                proc = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    timeout=self.timeout_s
                )
                if proc.returncode != 0:
                    stderr = proc.stderr.decode('utf-8', errors='replace')
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package (not our own module)
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # Heuristic: if the error says "No module named '{mod}'", it's our fault.
                        if f"No module named '{mod}'" in stderr or f"No module named \"{mod}\"" in stderr:
                            import_errors.append(f"{mod}: Module not found")
                        else:
                            module_not_found_errors.append(f"{mod}: Dependency missing")
                    else:
                        import_errors.append(f"{mod}: {stderr}")
            except Exception as e:
                import_errors.append(f"{mod}: {e}")

        elapsed = time.time() - start

        if import_errors:
            return GateResult(name='smoke', status=FAILED, method='import', detail='; '.join(import_errors), duration_s=elapsed)

        if module_not_found_errors:
            return GateResult(name='smoke', status=SKIPPED, method='import', detail='; '.join(module_not_found_errors), duration_s=elapsed)

        return GateResult(name='smoke', status=PASSED, method='import', detail='All modules imported', duration_s=elapsed)

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='discover', detail='No test files found', duration_s=time.time() - start)

        # Construct PYTHONPATH
        env = os.environ.copy()
        pypath = [workdir, os.path.join(workdir, 'src')]
        env['PYTHONPATH'] = os.pathsep.join(pypath + [env.get('PYTHONPATH', '')])

        # Try pytest first
        try:
            # Check if pytest is installed
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], capture_output=True, timeout=10)

            # Run pytest
            proc = subprocess.run(
                [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                cwd=workdir,
                env=env,
                capture_output=True,
                timeout=self.timeout_s
            )
            elapsed = time.time() - start

            if proc.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed', duration_s=elapsed)
            elif proc.returncode == 1:
                return GateResult(name='tests', status=FAILED, method='pytest', detail='Test failures detected', duration_s=elapsed)
            else:
                stderr_text = proc.stderr.decode('utf-8', errors='replace') if proc.stderr else ''
                stdout_text = proc.stdout.decode('utf-8', errors='replace') if proc.stdout else ''
                combined = stderr_text + stdout_text
                if 'ModuleNotFoundError' in combined:
                    return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Tests skipped due to missing dependency', duration_s=elapsed)
                # Exit code 5 is 'no tests collected', which is a failure if not due to import error
                # Other non-zero codes are also failures
                return GateResult(name='tests', status=FAILED, method='pytest', detail=f'pytest exited with code {proc.returncode}', duration_s=elapsed)

        except FileNotFoundError:
            pass # pytest not found, fall back to stdlib
        except Exception:
            pass # pytest failed to run, fall back to stdlib

        # Stdlib fallback
        # We need to import each test file and run tests
        # This is complex to do in a single subprocess call robustly.
        # We'll write a small runner script.

        runner_code = """
import sys
import unittest
import importlib
import os

# Collect test files from argv
test_files = sys.argv[1:]
test_modules = []
for f in test_files:
    # Convert path to module name
    # Assuming cwd is workdir
    rel_path = os.path.relpath(f, os.getcwd())
    if rel_path.startswith('src/'):
        mod_name = rel_path[4:-3].replace('/', '.')
    else:
        mod_name = rel_path[:-3].replace('/', '.')
    try:
        mod = importlib.import_module(mod_name)
        test_modules.append(mod)
    except ModuleNotFoundError as e:
        print(f"MODULE_NOT_FOUND:{mod_name}:{e}")
        sys.exit(2)
    except Exception as e:
        print(f"IMPORT_ERROR:{mod_name}:{e}")
        sys.exit(1)

# Run tests
loader = unittest.TestLoader()
suite = unittest.TestSuite()

for mod in test_modules:
    # Add unittest.TestCase subclasses
    suite.addTests(loader.loadTestsFromModule(mod))

    # Add bare test_* functions
    for name in dir(mod):
        if name.startswith('test_'):
            func = getattr(mod, name)
            if callable(func) and not isinstance(func, type):
                # Check if it takes 0 required args
                import inspect
                sig = inspect.signature(func)
                params = sig.parameters
                # Allow self if it's a method, but we are looking for functions
                # If it's a function, it should take 0 args
                if len(params) == 0:
                    suite.addTest(unittest.FunctionTestCase(func))

runner = unittest.TextTestRunner(verbosity=2)
result = runner.run(suite)

if result.wasSuccessful():
    sys.exit(0)
else:
    sys.exit(1)
"""

        try:
            # Write runner to temp file
            runner_path = os.path.join(workdir, '_test_runner.py')
            with open(runner_path, 'w') as f:
                f.write(runner_code)

            # Run it
            proc = subprocess.run(
                [self.python_executable, '_test_runner.py'] + test_files,
                cwd=workdir,
                env=env,
                capture_output=True,
                timeout=self.timeout_s
            )
            elapsed = time.time() - start

            # Clean up
            try:
                os.remove(runner_path)
            except:
                pass

            stdout = proc.stdout.decode('utf-8', errors='replace')
            stderr = proc.stderr.decode('utf-8', errors='replace')

            if proc.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='unittest', detail='All tests passed', duration_s=elapsed)
            elif proc.returncode == 1:
                return GateResult(name='tests', status=FAILED, method='unittest', detail='Test failures detected', duration_s=elapsed)
            elif proc.returncode == 2:
                return GateResult(name='tests', status=SKIPPED, method='unittest', detail='Tests skipped due to missing dependency', duration_s=elapsed)
            else:
                return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Runner exited with code {proc.returncode}', duration_s=elapsed)

        except Exception as e:
            elapsed = time.time() - start
            return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Runner error: {e}', duration_s=elapsed)

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for py_file in python_files:
            full_path = os.path.join(workdir, py_file)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                tree = ast.parse(content)

                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Direct call: get_tracer()
                        if isinstance(func, ast.Name) and func.id in tracer_methods:
                            has_call = True
                        # Method call: tracer.start_span()
                        elif isinstance(func, ast.Attribute) and func.attr in tracer_methods:
                            has_call = True

            except Exception:
                pass

        elapsed = time.time() - start

        if has_import and has_call:
